/// Whether the COMMITTED store holds this record WITH A BODY.
///
/// "Is the id there" is not the question, and answering that one cost a crate a test. `impl set`
/// authors a record from its DECLARATION — role, name, `moduleVis`, `moduleAttrs` — so a lift that
/// named the id from `extract::harvest_module` but never DELEGATED the harvest stored
/// `bsc-sound--tests.rs` with every field except `code`. It materialized as an empty `mod tests {}`,
/// which is valid Rust, so `cargo check --all-targets` passed and the crate silently went from 20
/// tests to 19. Nothing but the before/after count saw it.
///
/// One predicate for all three promote sites, because a body-less record is the same lie whichever
/// one wrote it.
pub(crate) fn landed_with_a_body(repo: &serde_json::Value, id: &str) -> bool {
    repo.get("implementations")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
        .find(|i| i.get("id").and_then(|x| x.as_str()) == Some(id))
        .and_then(|i| i.get("code").and_then(serde_json::Value::as_str))
        .is_some_and(|c| !c.trim().is_empty())
}
